-- pre-data: everything the load needs to exist before it starts.
--
-- The module's default target_table_prep_mode is DO_NOTHING, so DMS creates
-- none of this. A missing table does not fail the task - it suspends that one
-- table, which reads as a partial success.
--
-- Generated by the schema conversion step, reviewed, then committed here.

CREATE SCHEMA IF NOT EXISTS core;
CREATE SCHEMA IF NOT EXISTS dms_control;

-- Surrogate keys are identity columns, BY DEFAULT so DMS can insert the values
-- it carries over from the source (GENERATED ALWAYS would reject them). They
-- are what gives 03-post-data-sequences.sql a sequence to reset.
--
-- Tables and their primary keys. The primary key belongs here, not in
-- post-data: a full-load-and-cdc task applies the changes cached during the
-- load as soon as each table finishes, and on a table without a key every
-- UPDATE and DELETE is a full scan - CDC falls behind and may never catch up.
-- A primary key rejects nothing that arrives parent-last; foreign keys do,
-- and they stay in post-data with the secondary indexes and grants.
--
-- Oracle DATE carries a time of day: it maps to timestamp(0), not date, which
-- would drop the time. A zone-less source value goes to timestamp, not
-- timestamptz, which would read it in the DMS session's time zone.
CREATE TABLE IF NOT EXISTS core.account (
  account_id      bigint        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id     bigint        NOT NULL,
  opened_on       timestamp(0)  NOT NULL,
  status          varchar(16)   NOT NULL,
  balance_minor   bigint        NOT NULL
);

CREATE TABLE IF NOT EXISTS core.customer (
  customer_id     bigint        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  full_name       varchar(200)  NOT NULL,
  created_on      timestamp(0)  NOT NULL
);
